function [rho] = density_at(h, t_epoch)
%DENSITY_AT  The neutral density at altitude h: rho0 exp(-(h - h0)/H) in the table's band. The epoch does not
%   enter yet: the solar-activity dependence waits on the nrlmsis2 bundle (docs/ADCS_GAPS.md).
%   h: real[km] (passed in m)
%   t_epoch: real[yr] (passed in s)
%   returns rho: real[kg/m^3] (passed in kg/m^3)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    rho = 0;
    [h0, rho0, scale] = asils.physics.env.atmosphere(h);
    rho = (rho0 * exp(((-((h - h0))) / scale)));
end
